text:
{
 "title": "デジタル社会形成基本法",
 "lead": {
  "es": "デジタル社会《しゃかい》をつくるための 考《かんが》え方《かた》や、国《くに》などの役目《やくめ》、デジタル庁《ちょう》を置《お》くことなどを決《き》めた 新《あたら》しい法律《ほうりつ》です。",
  "hs": "デジタル社会をつくるための｜施策《しさく》を進めるため、基本理念、国・地方公共団体・事業者の｜責務《せきむ》、デジタル庁の設置、重点計画の作成などを定めた新しい法律です。",
  "std": "デジタル社会の形成に関する施策を迅速かつ重点的に推進するため、基本理念、施策の基本方針、国・地方公共団体・事業者の責務、デジタル庁の設置、重点計画の作成について定めた法律です。",
  "univ": "デジタル社会の形成に関する施策を迅速かつ重点的に推進し、我が国経済の持続的かつ健全な発展と国民の幸福な生活の実現に寄与するため、基本理念及び施策の策定に係る基本方針、国、地方公共団体及び事業者の責務、デジタル庁の設置並びに重点計画の作成について定める法律。"
 },
 "facts": [
  {
   "es": "「デジタル社会《しゃかい》」とは、インターネットなどで 世界中《せかいじゅう》の情報《じょうほう》を自由《じゆう》に安全《あんぜん》にやりとりし、情報《じょうほう》を生《い》かして いろいろな分野《ぶんや》で 新《あたら》しく元気《げんき》に発展《はってん》できる社会《しゃかい》のことだと 決《き》めます。",
   "hs": "「デジタル社会」とは、高度な情報通信ネットワークを通じて世界中の情報や知識を自由かつ安全に手に入れ、共有し、発信し、情報通信技術で情報を生かすことで、あらゆる分野で創造的で活力ある発展ができる社会のことだと定める。",
   "std": "「デジタル社会」を、高度情報通信ネットワークを通じて自由かつ安全に多様な情報・知識を世界的規模で入手・共有・発信し、情報通信技術を用いた情報の活用により、あらゆる分野で創造的かつ活力ある発展が可能となる社会と定義します。",
   "univ": "この法律において「デジタル社会」とは、高度情報通信ネットワークを通じて自由かつ安全に多様な情報又は知識を世界的規模で入手し、共有し、又は発信するとともに、情報通信技術を用いた情報の活用により、あらゆる分野における創造的かつ活力ある発展が可能となる社会をいう。"
  },
  {
   "es": "ゆとりと豊《ゆた》かさを感《かん》じられるくらし、安全《あんぜん》で安心《あんしん》なくらし、使《つか》える機会《きかい》などの差《さ》をなくすこと、一人《ひとり》ひとりや会社《かいしゃ》の権利《けんり》を守《まも》ることなどを、基本《きほん》の考《かんが》え方《かた》として決《き》めます。",
   "hs": "ゆとりと豊かさを実感できる生活、安全で安心してくらせる社会の実現、利用の機会などの｜格差《かくさ》をなくすこと、個人や法人の権利と利益を守ることなどを基本理念として定める。",
   "std": "ゆとりと豊かさを実感できる国民生活の実現、安全で安心して暮らせる社会の実現、利用の機会等の格差の是正、個人・法人の権利利益の保護等を基本理念として定めます。",
   "univ": "デジタル社会の形成に関し、ゆとりと豊かさを実感できる国民生活の実現、国民が安全で安心して暮らせる社会の実現、利用の機会等の格差の是正、個人及び法人の権利利益の保護等の基本理念を定める。"
  },
  {
   "es": "国《くに》がすることを決《き》めるときは、情報《じょうほう》がスムーズに流《なが》れること、だれでも使《つか》える機会《きかい》があること、人《ひと》を育《そだ》てること、国《くに》や役所《やくしょ》の情報《じょうほう》を国民《こくみん》が使《つか》えること、基本《きほん》の情報《じょうほう》をまとめたデータベースをつくること、インターネットの安全《あんぜん》を守《まも》ること、個人《こじん》の情報《じょうほう》を守《まも》ることなどに 気《き》をつけるという方針《ほうしん》を決《き》めます。",
   "hs": "｜施策《しさく》をつくるときは、情報が円滑に流れること、ネットワークや情報通信技術を使う機会の確保、人材の育成、生産性やくらしの便利さの向上、国や地方公共団体が持つ情報の国民による活用、公的基礎情報データベースの整備、サイバーセキュリティ（ネット上の安全）の確保、個人情報の保護などのために必要な｜措置《そち》をとらなければならない、という基本方針を定める。",
   "std": "施策の策定に当たっては、多様な主体による情報の円滑な流通の確保、ネットワーク利用と情報活用の機会の確保、人材の育成、生産性や生活の利便性の向上、国民による国・地方公共団体の保有情報の活用、公的基礎情報データベースの整備、サイバーセキュリティの確保、個人情報の保護等のために必要な措置を講じなければならない旨の基本方針を定めます。",
   "univ": "デジタル社会の形成に関する施策の策定に当たっては、多様な主体による情報の円滑な流通の確保、高度情報通信ネットワークの利用及び情報通信技術を用いた情報の活用の機会の確保、人材の育成、生産性や国民生活の利便性の向上、国民による国及び地方公共団体が保有する情報の活用、公的基礎情報データベースの整備、サイバーセキュリティの確保、個人情報の保護等のために必要な措置が講じられなければならない旨の基本方針を定める。"
  },
  {
   "es": "国《くに》、都道府県《とどうふけん》や市町村《しちょうそん》、会社《かいしゃ》などの役目《やくめ》を決《き》めます。別《べつ》の法律《ほうりつ》にしたがって、内閣《ないかく》に デジタル庁《ちょう》を置《お》きます。政府《せいふ》は、とくに力《ちから》を入《い》れる計画《けいかく》（重点《じゅうてん》計画《けいかく》）をつくらなければなりません。",
   "hs": "国・地方公共団体・事業者の｜責務《せきむ》などを定める。別の法律で定めるところにより、内閣にデジタル庁を置く。政府は、デジタル社会づくりの重点計画をつくらなければならない。",
   "std": "国・地方公共団体・事業者の責務等を定めます。別に法律で定めるところにより内閣にデジタル庁を置き、政府はデジタル社会の形成に関する重点計画を作成しなければならないこととします。",
   "univ": "デジタル社会の形成に関し、国、地方公共団体及び事業者の責務等を定める。別に法律で定めるところにより、内閣に、デジタル庁を置く。政府は、デジタル社会の形成に関する重点計画を作成しなければならない。"
  },
  {
   "es": "衆議院《しゅうぎいん》で、法律案《ほうりつあん》の一部《いちぶ》が直《なお》されました。なくしていく差《さ》の原因《げんいん》の言葉《ことば》を「体《からだ》の条件《じょうけん》」から「障害《しょうがい》があるかないかなど 心《こころ》や体《からだ》の状態《じょうたい》」に変《か》え、国《くに》などがすることに「公平《こうへい》にお金《かね》を配《くば》ったり 負担《ふたん》したりすること」のための準備《じゅんび》を加《くわ》えるなどしました。",
   "hs": "衆議院で修正が行われた。なくすべき利用の機会などの｜格差《かくさ》の原因について「身体的な条件」を「障害の有無などの心身の状態」に改め、国や地方公共団体が行う｜施策《しさく》に「公正な給付と負担の確保」のための環境整備を加えることなどが内容。",
   "std": "衆議院で、是正すべき利用の機会等の格差の要因について「身体的な条件」を「障害の有無等の心身の状態」に改めること、国・地方公共団体の施策に「公正な給付と負担の確保」のための環境整備を追加すること等を内容とする修正が行われました。",
   "univ": "本法律案は、衆議院において、デジタル社会の形成に当たって是正が図られなければならない利用の機会等の格差の要因について、「身体的な条件」を「障害の有無等の心身の状態」に改めること、デジタル社会の形成に当たって国及び地方公共団体が行う施策に「公正な給付と負担の確保」のための環境整備を追加すること等を内容とする修正が行われた。"
  },
  {
   "es": "この法律《ほうりつ》は、令和《れいわ》3年《ねん》9月《がつ》1日《ついたち》から使《つか》われます。それまでの「高度《こうど》情報《じょうほう》通信《つうしん》ネットワーク社会《しゃかい》形成《けいせい》基本法《きほんほう》」はなくなります。",
   "hs": "この法律は、令和3年9月1日から｜施行《しこう》する。高度情報通信ネットワーク社会形成基本法は｜廃止《はいし》する。",
   "std": "令和3年9月1日から施行し、高度情報通信ネットワーク社会形成基本法は廃止します。",
   "univ": "この法律は、令和3年9月1日から施行する。高度情報通信ネットワーク社会形成基本法は、廃止する。"
  }
 ]
}
